import { cookies } from "next/headers";
import { SignJWT, jwtVerify } from "jose";
import bcrypt from "bcryptjs";
import { db } from "../infra/db";

/**
 * Session auth: a signed cookie, nothing more.
 *
 * No OAuth provider, no hosted identity service, no third party. The product
 * is single-operator by design — it runs on your machine, reads your mail and
 * sends as you — so a password and a signed cookie is the whole requirement,
 * and anything more would be a dependency with a free tier that expires.
 *
 * `AUTH_SECRET` is generated by `npm run setup`. The console refuses to issue
 * a session on the placeholder value, because a predictable signing key on
 * something that can send mail as you is not a warning, it is a hole.
 */

const COOKIE = "mercurio_session";
const MAX_AGE_SECONDS = 60 * 60 * 24 * 14;
const PLACEHOLDER = "change-me-to-something-random";

function secret(): Uint8Array {
  const value = process.env.AUTH_SECRET ?? "";
  if (!value || value === PLACEHOLDER) {
    throw new Error(
      "AUTH_SECRET is unset or still the placeholder. Set it to a random string — `openssl rand -hex 32` — and restart.",
    );
  }
  if (value.length < 24) {
    throw new Error("AUTH_SECRET is too short; use at least 24 characters.");
  }
  return new TextEncoder().encode(value);
}

export interface Session {
  userId: string;
  email: string;
}

export async function createSession(session: Session): Promise<void> {
  const token = await new SignJWT({ email: session.email })
    .setProtectedHeader({ alg: "HS256" })
    .setSubject(session.userId)
    .setIssuedAt()
    .setExpirationTime(`${MAX_AGE_SECONDS}s`)
    .sign(secret());

  (await cookies()).set(COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: MAX_AGE_SECONDS,
  });
}

export async function readSession(): Promise<Session | null> {
  const token = (await cookies()).get(COOKIE)?.value;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, secret());
    if (!payload.sub) return null;
    return { userId: payload.sub, email: String(payload.email ?? "") };
  } catch {
    // An expired or tampered token is simply no session.
    return null;
  }
}

export async function destroySession(): Promise<void> {
  (await cookies()).delete(COOKIE);
}

/**
 * The signed-in user, or null.
 *
 * Re-read from the database rather than trusted from the cookie, so a deleted
 * account cannot keep acting on a token that has not expired yet.
 */
export async function currentUser() {
  const session = await readSession();
  if (!session) return null;
  return db.user.findUnique({ where: { id: session.userId } });
}

export async function verifyPassword(email: string, password: string) {
  const user = await db.user.findUnique({ where: { email: email.trim().toLowerCase() } });
  // The hash comparison runs even when there is no such account, so a missing
  // account and a wrong password take the same time to answer.
  const hash = user?.passwordHash ?? "$2a$10$invalidinvalidinvalidinvalidinvalidinvalidinvalidinvalidinv";
  const matches = await bcrypt.compare(password, hash);
  return matches && user ? user : null;
}

/**
 * Scopes a campaign to its owner.
 *
 * Every query that reads campaign data goes through this. A campaign id from
 * the URL is a client-supplied value, and the only safe way to use one is to
 * require that it belongs to the session.
 */
export async function ownedCampaign(campaignId: string) {
  const session = await readSession();
  if (!session) return null;
  return db.campaign.findFirst({ where: { id: campaignId, userId: session.userId } });
}
